use system.fs
use system.os
use system.collections.list

fn main()
    let args = Args()
    println(f"argc {args.length()}")
    let path = args.element_at(0)
    println(f"path {path}")
    let fs = Fs()
    match fs.read_file(path)
        Result.Ok(c): println(f"[{c}] len {c.length()}")
        Result.Err(e): println("err")
    let spaced = "3 2 2\n0 1".replace("\n", " ")
    for part in spaced.split(" ")
        println(f"<{part}> {part.length()}")
EOF
